/** 与 loader 所在包根一致；瘦包内仍用相对路径，开发 monorepo 对齐 VENUE_ADAPTER_ROOT */
const ADAPTER_ROOT = fs.existsSync(path.join(VENUE_ADAPTER_ROOT, "registry", "manifest.json"))
