      if (!fs.existsSync(file)) continue;
      const pkg = json(file);
      if (!pkg.name || packages.has(pkg.name)) throw Error(`Invalid/duplicate workspace: ${dir}`);
      packages.set(pkg.name, { dir, pkg });
